test_suite:
test('reads pass through', () => {
  const obj = readOnly({ name: 'Alice', score: 10 });
  expect(obj.name).toBe('Alice');
  expect(obj.score).toBe(10);
});

test('any write throws TypeError', () => {
  const obj = readOnly({ x: 1 });
  expect(() => { obj.x = 2; }).toThrow(TypeError);
});

test('setting new property also throws', () => {
  const obj = readOnly({});
  expect(() => { obj.newProp = 'value'; }).toThrow(TypeError);
});

// __hidden__
test('delete throws TypeError', () => {
  const obj = readOnly({ a: 1 });
  expect(() => { delete obj.a; }).toThrow(TypeError);
});

solution:
export function readOnly(obj) {
  return new Proxy(obj, {
    set(target, prop, value, receiver) {
      throw new TypeError(`Cannot set property '${String(prop)}' on read-only object`);
    },
    deleteProperty(target, prop) {
      throw new TypeError(`Cannot delete property '${String(prop)}' on read-only object`);
    }
  });
}
